"""Print the API's OpenAPI document: `uv run python -m sentinel_api.openapi > schemas/openapi.yaml`."""

from __future__ import annotations

import sys

import yaml

from sentinel_api.config import Settings
from sentinel_api.main import create_app


def render() -> str:
    document = create_app(Settings(database_url=None, token_sha256=frozenset())).openapi()
    header = (
        "# Platform API v1 (SPEC section 13.3). Generated by `python -m sentinel_api.openapi`: do not edit.\n"
    )
    return header + yaml.safe_dump(document, sort_keys=False, allow_unicode=True)


if __name__ == "__main__":
    sys.stdout.write(render())
